  "workspace.generateBriefDefault":
    "【必须遵守】\n1）衔接勾选章节的大纲与记忆：既定事实不得推翻。\n2）落实本章大纲关键节拍与链接剧情卡要点。\n3）人物言行符合链接人物卡；未链接设定勿硬塞。\n4）遵守链接知识卡与知识库策略边界。\n5）篇幅以根节点每章目标为准，允许 ±60；禁止低于有效下限或超过有效上限。\n6）禁止参考本章已有正文/旧稿，须按材料重新写出完整正文。\n7）只输出本章 Markdown 正文，勿输出清单或自我评分。\n（可在下方补充你的额外要求）",
