  "workspace.refineBriefDefault":
    "【必须遵守】\n1）必须在当前章已有正文底稿上修改；禁止丢弃原文另起炉灶重写。\n2）不大改剧情：保留原有情节骨架与段落顺序，只改矛盾、不合理、不通顺、未落地与字数越界处。\n3）历史只读：前序章（记忆/大纲或全文）仅作核对，禁止改写历史。\n4）衔接合理：与历史因果、人物关系、时间线一致；链接剧情卡要点勿缺。\n5）篇幅以根节点每章目标为准，允许 ±60；禁止低于有效下限或超过有效上限。\n6）输出完整当前章 Markdown；文末用列表归并修正点。\n（可在下方补充你的额外要求）",
