  "workspace.generateBriefPh": "Edit constraints and extra requirements…",
  "workspace.generateBriefDefault":
    "[Must follow]\n1) Continue checked chapters’ outlines and memory — do not overturn facts.\n2) Land this chapter’s outline beats and linked plot-card points.\n3) Stay in character for linked cards; don’t force unlinked lore.\n4) Respect linked knowledge cards and knowledge strategy.\n5) Length: root per-chapter target ±60; must not go below the lower band or above the upper band.\n6) Do not use any existing body/draft of this chapter — write a full new body from the materials.\n7) Output only this chapter’s Markdown body — no checklist or self-score.\n(Add any extra requirements below.)",
