  "workspace.refineBriefPh": "Add focus areas or extra requirements…",
  "workspace.refineBriefDefault":
    "[Must follow]\n1) Edit the existing current-chapter body in place — do not discard it and rewrite from scratch.\n2) No plot overhaul: keep beats and paragraph order; fix only contradictions, errors, awkward prose, missing landings, and out-of-band length.\n3) History is read-only: prior chapters (memory/outlines or full text) for checking only.\n4) Continuity: match history, relationships, timeline; keep linked plot-card beats.\n5) Length: root per-chapter target ±60; must not go below the lower band or above the upper band.\n6) Output full current chapter Markdown; end with a categorized fix list.\n(Add any extra requirements below.)",
