  "workspace.generateBriefDefault":
    "【必須遵守】\n1）銜接勾選章節的大綱與記憶：既定事實不得推翻。\n2）落實本章大綱關鍵節拍與連結劇情卡要點。\n3）人物言行符合連結人物卡；未連結設定勿硬塞。\n4）遵守連結知識卡與知識庫策略邊界。\n5）篇幅以根節點每章目標為準，允許 ±60；禁止低於有效下限或超過有效上限。\n6）禁止參考本章已有正文/舊稿，須按材料重新寫出完整正文。\n7）只輸出本章 Markdown 正文，勿輸出清單或自我評分。\n（可在下方補充你的額外要求）",
  "workspace.generateConfirmHint": "修改後的條件會記住為預設；「重置條件」恢復出廠缺省。預設不勾選歷史記憶；需要時再勾選作剎車。進行中劇情卡會自動注入。",
