  "workspace.refineBriefDefault":
    "【必須遵守】\n1）必須在當前章已有正文底稿上修改；禁止丟棄原文另起爐灶重寫。\n2）不大改劇情：保留原有情節骨架與段落順序，只改矛盾、不合理、不通順、未落地與字數越界處。\n3）歷史唯讀：前序章（記憶/大綱或全文）僅作核對，禁止改寫歷史。\n4）銜接合理：與歷史因果、人物關係、時間線一致；連結劇情卡要點勿缺。\n5）篇幅以根節點每章目標為準，允許 ±60；禁止低於有效下限或超過有效上限。\n6）輸出完整當前章 Markdown；文末用列表歸併修正點。\n（可在下方補充你的額外要求）",
