    "【必須】\n1）本章の既存本文を底稿として改修する。捨てて一から書き直さない。\n2）筋は大きく変えない：骨格と段落順を保ち、矛盾・不合理・不自然・未着地・字数逸脱だけ直す。\n3）履歴は参照のみ：先行章（記憶/アウトラインまたは全文）を書き換えない。\n4）整合：因果・人物関係・時系列を合わせ、リンク筋書き要点を欠かさない。\n5）字数はルートの章目標±60；有効下限未満・上限超過は禁止。\n6）本章 Markdown 全文を出力し、末尾に修正点リスト。\n（下に追加要件を書ける）",
