  "workspace.generateBriefPh": "Vorgaben und Extra-Anforderungen bearbeiten…",
  "workspace.generateBriefDefault":
    "[Pflicht]\n1) Angehakte Kapitel-Outlines und Gedächtnis fortführen — Fakten nicht umstoßen.\n2) Outline-Beats und Plotkarten umsetzen.\n3) Figurenkarten einhalten; unverknüpftes nicht erzwingen.\n4) Wissens­karten und Strategie beachten.\n5) Länge: Wurzelziel ±60; unter untere bzw. über obere Bandgrenze verboten.\n6) Bestehenden Text/Entwurf dieses Kapitels nicht nutzen — neu aus den Materialien schreiben.\n7) Nur Markdown-Kapiteltext ausgeben.\n(Weitere Anforderungen unten.)",
  "workspace.generateConfirmHint": "Änderungen werden gespeichert. „Zurücksetzen“ stellt die Werkseinstellung wieder her. Gedächtnis standardmäßig aus; aktive Plots fließen ein.",
  "workspace.generateBriefReset": "Bedingungen zurücksetzen",
