  "workspace.refineConfirmTitle": "Verfeinern bestätigen",
  "workspace.refineBriefLabel": "Verfeinerungsbedingungen",
  "workspace.refineBriefPh": "Schwerpunkte oder Extra-Anforderungen…",
  "workspace.refineBriefDefault":
    "[Pflicht]\n1) Den vorhandenen Kapiteltext als Vorlage bearbeiten — nicht verwerfen und neu schreiben.\n2) Handlung kaum ändern: Gerüst und Absatzreihenfolge behalten; nur Widersprüche, Fehler, holprige Stellen, fehlende Beats und Bandüberschreitung.\n3) Historie nur lesen: Vor-Kapitel (Gedächtnis/Outlines oder Volltext) nicht umschreiben.\n4) Kontinuität: Kausalität, Beziehungen, Zeitlinie; Plotkarten-Beats behalten.\n5) Länge: Wurzelziel ±60; unter untere bzw. über obere Bandgrenze verboten.\n6) Volles Kapitel-Markdown; am Ende Fix-Liste nach Kategorien.\n(Weitere Anforderungen unten.)",
