  "workspace.memoryExtractNotesDefault":
    "[Pflichtblöcke]\n1) Gesamtplot: 1–3 Absätze zur Ereigniskette und Kausalität — detaillierter als Outline (Szenen, Konflikte, Ergebnisse), ca. 150–400 Wörter. Keine langen Dialoge/Beschreibungen abschreiben.\n2) Fakten: anwesende Figuren; Handlungen; Ziele; Versprechen; Persönlichkeit.\n[Format]\n[Gesamtplot]\n…\n[Fakten]\n- Figur: … | Handlung: … | Ziel: … | Versprechen: … | Persona: … (leere Felder weglassen; eine Zeile pro Punkt)\nNur Fakten aus diesem Kapitel; wenn fast leer: Gesamtplot „(keine)“ und `- (kein Kerngedächtnis)`.\n(Weitere Anforderungen unten ergänzen.)",
