  "workspace.generateBriefPh": "Modifiez contraintes et exigences…",
  "workspace.generateBriefDefault":
    "[Obligatoire]\n1) Continuer plans et mémoire des chapitres cochés — ne pas contredire les faits.\n2) Faire aboutir les points du plan et des cartes intrigue.\n3) Respecter les personnages liés ; ne pas forcer le non lié.\n4) Respecter cartes connaissance et stratégie.\n5) Longueur : cible racine ±60 ; interdit sous la borne basse ou au-dessus de la borne haute.\n6) Ne pas utiliser le corps/brouillon existant de ce chapitre — réécrire à partir des matériaux.\n7) Sortir uniquement le Markdown du chapitre.\n(Ajoutez d’autres exigences en dessous.)",
  "workspace.generateConfirmHint": "Vos modifications deviennent la valeur par défaut. Mémoire décochée par défaut ; intrigues actives injectées automatiquement.",
