  "workspace.refineBriefPh": "Ajoutez des priorités ou exigences…",
  "workspace.refineBriefDefault":
    "[Obligatoire]\n1) Modifier le texte existant du chapitre en place — ne pas le jeter pour tout réécrire.\n2) Pas de refonte d’intrigue : garder squelette et ordre des paragraphes ; corriger contradictions, erreurs, prose, beats manquants, hors bande.\n3) Historique en lecture seule : chapitres précédents (mémoire/plans ou texte) non réécrits.\n4) Continuité : causalité, relations, chronologie ; garder les beats des cartes intrigue.\n5) Longueur : cible racine ±60 ; interdit sous la borne basse ou au-dessus de la borne haute.\n6) Sortir le Markdown complet du chapitre ; liste de corrections en fin.\n(Ajoutez d’autres exigences en dessous.)",
